// Normalise la reponse d'Ollama en champs stables.
// Supporte : structured outputs (format=schema), JSON brut, ou texte avec objet imbrique.
const data = $input.first().json;
const theme = $('Theme Picker').first().json.theme;

const raw = data.response ?? data.message?.content ?? '';
let parsed = null;

const tryParse = (s) => { try { return JSON.parse(s); } catch (_) { return null; } };

if (typeof raw === 'object' && raw !== null) parsed = raw;
else {
  parsed = tryParse(String(raw));
  if (!parsed) {
    const m = String(raw).match(/\{[\s\S]*\}/);
    if (m) parsed = tryParse(m[0]);
  }
}

const field = (k) => {
  const v = parsed?.[k];
  return typeof v === 'string' ? v.trim() : '';
};

const hook = field('hook');
const body = field('body');
const call_to_action = field('call_to_action');

if (!hook && !body && !call_to_action && !parsed) {
  throw new Error(`Reponse LLM inexploitable (modele=${data.model ?? 'n/a'}). Brut: ${String(raw).slice(0, 300)}`);
}

return [{
  json: {
    theme,
    hook,
    body,
    call_to_action,
    complete: !!(hook && body && call_to_action),
    model: data.model ?? 'llama3.2:3b',
    total_duration_ms: typeof data.total_duration === 'number' ? Math.round(data.total_duration / 1e6) : null,
    raw_preview: String(raw).slice(0, 300)
  }
}];

